-- -----------------------------------------------
-- Table structure for `personnel`
-- -----------------------------------------------

DROP TABLE IF EXISTS `personnel`;
CREATE TABLE `personnel` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `personal_number` varchar(50) NOT NULL,
  `name` varchar(150) NOT NULL,
  `photo_path` varchar(255) DEFAULT NULL,
  `rank_id` int(11) DEFAULT NULL,
  `unit_id` int(11) DEFAULT NULL,
  `cadre_id` int(11) DEFAULT NULL,
  `platoon_id` int(11) DEFAULT NULL,
  `blood_group_id` int(11) DEFAULT NULL,
  `batch` varchar(100) DEFAULT NULL,
  `mobile_number` varchar(20) DEFAULT NULL,
  `address` text DEFAULT NULL,
  `status` varchar(50) DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `appointment_id` int(11) DEFAULT NULL,
  `detailed_address` text DEFAULT NULL,
  `vill` varchar(255) DEFAULT NULL,
  `po` varchar(255) DEFAULT NULL,
  `ps` varchar(255) DEFAULT NULL,
  `nid` varchar(20) DEFAULT NULL,
  `moq_na` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `personal_number` (`personal_number`),
  KEY `rank_id` (`rank_id`),
  KEY `unit_id` (`unit_id`),
  KEY `cadre_id` (`cadre_id`),
  KEY `platoon_id` (`platoon_id`),
  KEY `blood_group_id` (`blood_group_id`),
  KEY `fk_personnel_appointment` (`appointment_id`),
  CONSTRAINT `fk_personnel_appointment` FOREIGN KEY (`appointment_id`) REFERENCES `appointments` (`id`),
  CONSTRAINT `personnel_ibfk_1` FOREIGN KEY (`rank_id`) REFERENCES `ranks` (`id`),
  CONSTRAINT `personnel_ibfk_2` FOREIGN KEY (`unit_id`) REFERENCES `units` (`id`),
  CONSTRAINT `personnel_ibfk_3` FOREIGN KEY (`cadre_id`) REFERENCES `cadres` (`id`),
  CONSTRAINT `personnel_ibfk_4` FOREIGN KEY (`platoon_id`) REFERENCES `platoons` (`id`),
  CONSTRAINT `personnel_ibfk_5` FOREIGN KEY (`blood_group_id`) REFERENCES `blood_groups` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=135 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

