-- -----------------------------------------------
-- Table structure for `personnel_approvals`
-- -----------------------------------------------

DROP TABLE IF EXISTS `personnel_approvals`;
CREATE TABLE `personnel_approvals` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `action_type` enum('add','edit','delete') NOT NULL,
  `personnel_id` int(11) DEFAULT NULL,
  `proposed_data` longtext NOT NULL,
  `previous_data` longtext DEFAULT NULL,
  `requested_by` int(11) NOT NULL,
  `requested_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `status` enum('pending','approved','rejected') DEFAULT 'pending',
  `reviewed_by` int(11) DEFAULT NULL,
  `reviewed_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `requested_by` (`requested_by`),
  KEY `reviewed_by` (`reviewed_by`),
  CONSTRAINT `personnel_approvals_ibfk_1` FOREIGN KEY (`requested_by`) REFERENCES `users` (`id`),
  CONSTRAINT `personnel_approvals_ibfk_2` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

