-- -----------------------------------------------
-- Table structure for `personnel_cadres`
-- -----------------------------------------------

DROP TABLE IF EXISTS `personnel_cadres`;
CREATE TABLE `personnel_cadres` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `personnel_id` int(11) NOT NULL,
  `cadre_id` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `personnel_id` (`personnel_id`),
  KEY `cadre_id` (`cadre_id`),
  CONSTRAINT `personnel_cadres_ibfk_1` FOREIGN KEY (`personnel_id`) REFERENCES `personnel` (`id`) ON DELETE CASCADE,
  CONSTRAINT `personnel_cadres_ibfk_2` FOREIGN KEY (`cadre_id`) REFERENCES `cadres` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1045 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

