-- -----------------------------------------------
-- Table structure for `personnel_health`
-- -----------------------------------------------

DROP TABLE IF EXISTS `personnel_health`;
CREATE TABLE `personnel_health` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `personnel_id` int(11) NOT NULL,
  `medical_category_id` int(11) DEFAULT NULL,
  `height_cm` decimal(5,2) DEFAULT NULL,
  `weight_kg` decimal(5,2) DEFAULT NULL,
  `any_disease` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `personnel_id` (`personnel_id`),
  KEY `medical_category_id` (`medical_category_id`),
  CONSTRAINT `personnel_health_ibfk_1` FOREIGN KEY (`personnel_id`) REFERENCES `personnel` (`id`) ON DELETE CASCADE,
  CONSTRAINT `personnel_health_ibfk_2` FOREIGN KEY (`medical_category_id`) REFERENCES `medical_categories` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=681 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

