-- -----------------------------------------------
-- Table structure for `personnel_moqs`
-- -----------------------------------------------

DROP TABLE IF EXISTS `personnel_moqs`;
CREATE TABLE `personnel_moqs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `personnel_id` int(11) NOT NULL,
  `moq_id` int(11) NOT NULL,
  `result` varchar(100) DEFAULT NULL,
  `is_bypass` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `personnel_id` (`personnel_id`),
  KEY `moq_id` (`moq_id`),
  CONSTRAINT `personnel_moqs_ibfk_1` FOREIGN KEY (`personnel_id`) REFERENCES `personnel` (`id`) ON DELETE CASCADE,
  CONSTRAINT `personnel_moqs_ibfk_2` FOREIGN KEY (`moq_id`) REFERENCES `moqs` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1023 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

