-- -----------------------------------------------
-- Table structure for `personnel_yearly_records`
-- -----------------------------------------------

DROP TABLE IF EXISTS `personnel_yearly_records`;
CREATE TABLE `personnel_yearly_records` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `personnel_id` int(11) NOT NULL,
  `record_year` int(11) NOT NULL,
  `ipft_1st` varchar(255) DEFAULT NULL,
  `ipft_2nd` varchar(255) DEFAULT NULL,
  `ret` varchar(255) DEFAULT NULL,
  `speed_march` varchar(255) DEFAULT NULL,
  `cycle_1` varchar(100) DEFAULT NULL,
  `cycle_2` varchar(100) DEFAULT NULL,
  `cycle_3` varchar(100) DEFAULT NULL,
  `cycle_4` varchar(100) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_personnel_year` (`personnel_id`,`record_year`),
  KEY `idx_personnel_year` (`personnel_id`,`record_year`),
  KEY `idx_record_year` (`record_year`),
  CONSTRAINT `fk_yearly_records_personnel` FOREIGN KEY (`personnel_id`) REFERENCES `personnel` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=171 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

